using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using LineGeometry97;
public static class RowLifetimeTests103 {
 public static void Main(){int checks=0;var empty=new List<Triangle>();var scene=new Scene(empty,new P(),4);var view=scene.ForkQueries103();try{scene.Rebuild(empty,new P());throw new Exception("rebuild entered live query lease");}catch(InvalidOperationException){checks++;}if(view.QueryVisible99(new P(1,1),1,new P()).state!=1)throw new Exception("read view lost geometry");checks++;
  Task.Factory.StartNew(()=>{try{scene.Rebuild(empty,new P());throw new Exception("foreign mutation accepted");}catch(InvalidOperationException){}}).Wait();checks++;view.ReleaseQueries103();view.ReleaseQueries103();if(scene.ActiveQueryViews103!=0)throw new Exception("query lease leaked");checks++;try{view.QueryVisible99(new P(1,1),1,new P());throw new Exception("expired query accepted");}catch(InvalidOperationException){checks++;}scene.Rebuild(empty,new P());
  var raster=new Raster(scene,new P(),4,new P());var collector=new CurveOpacity98(scene,raster);collector.Register(1,new P(.25,.25),new P(3.75,.25),.1);var strips=new List<Strip103>{new Strip103(new Triangle(new P(0,0),new P(4,0),new P(4,4),1,1,1,new P(),new P(),new P(),null),1,0,1,1),new Strip103(new Triangle(new P(0,0),new P(4,4),new P(0,4),1,1,1,new P(),new P(),new P(),null),1,0,1,0)};var stats=RowParallel103.Run(scene,raster,collector,strips);if(!stats.allWorkersCompleted||!stats.queryViewsReleased||scene.ActiveQueryViews103!=0)throw new Exception("row work released source early");checks++;try{collector.Register(2,new P(),new P(1,1),.1);throw new Exception("sealed feature table mutated");}catch(InvalidOperationException){checks++;}
  scene.Rebuild(empty,new P());raster=new Raster(scene,new P(),4,new P());collector=new CurveOpacity98(scene,raster);var excessive=new List<Strip103>();for(int i=0;i<1024;i++){collector.Register(i,new P(.25,.25),new P(3.75,.25),.1);foreach(var s in strips)excessive.Add(new Strip103(s.triangle,i,0,1,0));}try{RowParallel103.Run(scene,raster,collector,excessive);throw new Exception("bounded failure not reached");}catch(AggregateException){if(scene.ActiveQueryViews103!=0)throw new Exception("failed worker retained source lease");checks++;}scene.Rebuild(empty,new P());checks++;
  var shifted=new List<Strip103>{new Strip103(new Triangle(new P(0,0),new P(4,0),new P(4,1),1,1,1,new P(),new P(),new P(),null),1,0,1,1)};long top,bottom;int split=RowParallel103.Split103(raster,shifted,out top,out bottom);if(split!=1||top!=4||bottom!=4)throw new Exception("source candidate rows not balanced");checks++;
  Console.WriteLine("CPU103 lifetime checks="+checks+"; owner/read-only/generation/duplicate release/normal join/failure join/source-row partition; no Unity/GPU");
 }
}
